        when "ru"
          [
            rule_section(:play, "\u0412\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u0441 \u043A\u043E\u0441\u0442\u044F\u043C\u0438 \u0438 \u043E\u0447\u043A\u0438",
              "\u0418\u0433\u0440\u043E\u043A\u0438 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u0441\u0443\u043C\u043C\u0438\u0440\u0443\u044E\u0442 \u0431\u0440\u043E\u0441\u043A\u0438 \u0434\u043E 21. \u0414\u0432\u0435 \u043A\u043E\u0441\u0442\u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442\u0441\u044F \u043F\u0440\u0438 \u0441\u0443\u043C\u043C\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 16, \u0437\u0430\u0442\u0435\u043C \u043E\u0434\u043D\u0430. \u0412 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 \u041E\u0434\u043D\u0430 \u043A\u043E\u0441\u0442\u044C \u0432\u0441\u0435\u0433\u0434\u0430 \u0431\u0440\u043E\u0441\u0430\u044E\u0442 \u043E\u0434\u043D\u0443. \u041F\u043E\u0441\u043B\u0435 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0431\u0440\u043E\u0441\u043A\u0430 \u043C\u043E\u0436\u043D\u043E \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C\u0441\u044F. \u0414\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u0435 \u0438\u043B\u0438 \u043F\u0440\u0435\u0432\u044B\u0448\u0435\u043D\u0438\u0435 21 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u0445\u043E\u0434.",
              "\u041E\u0447\u043A\u0438 \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u044E\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u0445\u043E\u0434\u043E\u0432 \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432. \u0415\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u0430\u044F \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0430\u044F \u0441\u0443\u043C\u043C\u0430 \u0434\u043E 21 \u0434\u0430\u0451\u0442 \u043E\u0447\u043A\u043E, \u0440\u043E\u0432\u043D\u043E 21 \u2014 \u0434\u0432\u0430. \u0420\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u043E \u043B\u0443\u0447\u0448\u0438\u0445 \u0441\u0443\u043C\u043C, \u0432\u043A\u043B\u044E\u0447\u0430\u044F 21, \u0438\u043B\u0438 \u043F\u0435\u0440\u0435\u0431\u043E\u0440 \u0443 \u0432\u0441\u0435\u0445 \u043D\u0435 \u0434\u0430\u044E\u0442 \u043E\u0447\u043A\u043E\u0432. \u042D\u0442\u043E\u0442 \u0436\u0435 \u0441\u0447\u0451\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0441 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u044C\u044E \u0432\u043C\u0435\u0441\u0442\u043E \u043F\u0435\u0440\u0435\u0438\u0433\u0440\u043E\u0432\u043A\u0438. \u041D\u0430\u0447\u0438\u043D\u0430\u044E\u0449\u0438\u0439 \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043A\u0430\u0436\u0434\u044B\u0439 \u0440\u0430\u0443\u043D\u0434. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u0435\u0440\u0432\u044B\u0439, \u0434\u043E\u0441\u0442\u0438\u0433\u0448\u0438\u0439 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u043B\u0438\u043C\u0438\u0442\u0430, \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0434\u0435\u0441\u044F\u0442\u0438."),
            rule_section(:betting, "\u041D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u0439 \u0432\u0437\u043D\u043E\u0441 \u0438 \u0442\u043E\u0440\u0433\u0438",
              "\u041A\u0430\u0436\u0434\u044B\u0439 \u0440\u0430\u0443\u043D\u0434 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0441\u043E\u0431\u0438\u0440\u0430\u0435\u0442 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u0439 \u0432\u0437\u043D\u043E\u0441 \u0441 \u0430\u043A\u0442\u0438\u0432\u043D\u044B\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432: \u0434\u0435\u0441\u044F\u0442\u044C \u0444\u0438\u0448\u0435\u043A \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0438\u043B\u0438 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0441\u0442\u043E\u043B\u0430. \u0423 \u043A\u043E\u0433\u043E \u043C\u0435\u043D\u044C\u0448\u0435, \u0442\u043E\u0442 \u0432\u043D\u043E\u0441\u0438\u0442 \u0432\u0435\u0441\u044C \u0431\u0430\u043B\u0430\u043D\u0441 \u0438 \u0438\u0434\u0451\u0442 \u0432\u0430-\u0431\u0430\u043D\u043A. \u0417\u0430\u0442\u0435\u043C \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u043C\u043E\u0436\u043D\u043E \u043F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0442\u044C \u0431\u0435\u0437 \u0434\u043E\u043F\u043B\u0430\u0442\u044B, \u0443\u0440\u0430\u0432\u043D\u044F\u0442\u044C, \u043F\u043E\u0432\u044B\u0441\u0438\u0442\u044C, \u0441\u043F\u0430\u0441\u043E\u0432\u0430\u0442\u044C \u0438\u043B\u0438 \u043F\u043E\u0439\u0442\u0438 \u0432\u0430-\u0431\u0430\u043D\u043A. \u041F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043D\u043E\u0432\u043E\u0433\u043E \u043E\u0442\u0432\u0435\u0442\u0430 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445. \u0422\u043E\u0440\u0433\u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0442\u0441\u044F, \u043A\u043E\u0433\u0434\u0430 \u0432\u0441\u0435 \u0441 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u043C\u0438\u0441\u044F \u0444\u0438\u0448\u043A\u0430\u043C\u0438 \u043E\u0442\u0432\u0435\u0442\u0438\u043B\u0438 \u0438 \u0443\u0440\u0430\u0432\u043D\u044F\u043B\u0438 \u0441\u0442\u0430\u0432\u043A\u0443 \u043B\u0438\u0431\u043E \u043E\u0441\u0442\u0430\u043B\u0441\u044F \u043E\u0434\u0438\u043D \u043D\u0435 \u0441\u043F\u0430\u0441\u043E\u0432\u0430\u0432\u0448\u0438\u0439. \u0412\u0430-\u0431\u0430\u043D\u043A \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0431\u0435\u0437 \u0434\u0430\u043B\u044C\u043D\u0435\u0439\u0448\u0438\u0445 \u0442\u043E\u0440\u0433\u043E\u0432. \u041A\u043E\u0440\u043E\u0442\u043A\u0438\u0439 \u0432\u0430-\u0431\u0430\u043D\u043A \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435 \u0443\u0436\u0435 \u0445\u043E\u0434\u0438\u0432\u0448\u0435\u043C\u0443, \u043F\u043E\u043A\u0430 \u0441\u0443\u043C\u043C\u0430\u0440\u043D\u044B\u0439 \u0440\u043E\u0441\u0442 \u043D\u0435 \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0435\u0442 \u043F\u043E\u043B\u043D\u043E\u0433\u043E \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u044F.",
              "C \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u0438\u043B\u0438 \u0443\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u0435\u0442, F \u043F\u0430\u0441\u0443\u0435\u0442, A \u0438\u0434\u0451\u0442 \u0432\u0430-\u0431\u0430\u043D\u043A, R \u0438\u043B\u0438 B \u0432\u0432\u043E\u0434\u0438\u0442 \u0441\u0432\u043E\u0451 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435. \u0412\u0432\u043E\u0434\u0438\u0442\u0441\u044F \u043F\u0440\u0438\u0431\u0430\u0432\u043A\u0430 \u043A \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0441\u0442\u0430\u0432\u043A\u0435; \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u0435 \u0443\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u043D\u0438\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043A \u043F\u043B\u0430\u0442\u0435. \u041F\u0435\u0440\u0432\u043E\u0435 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435 \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 \u043E\u0434\u043D\u043E\u0439 \u0444\u0438\u0448\u043A\u0438, \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u043F\u043E\u043B\u043D\u043E\u0433\u043E \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u044F; \u043C\u0435\u043D\u044C\u0448\u0438\u0439 \u043A\u043E\u043D\u0435\u0447\u043D\u044B\u0439 \u0432\u0430-\u0431\u0430\u043D\u043A \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D. \u0413\u043E\u0442\u043E\u0432\u044B\u0435 \u0441\u0443\u043C\u043C\u044B \u0435\u0441\u0442\u044C \u0438 \u0432 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F\u0445. \u041A\u0430\u0440\u0442\u044B \u0438\u043B\u0438 \u0431\u0440\u043E\u0441\u043A\u0438 \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u044F \u0442\u043E\u0440\u0433\u043E\u0432."),
            rule_section(:chips, "\u0418\u0433\u0440\u0430 \u043D\u0430 \u0444\u0438\u0448\u043A\u0438",
              "\u041F\u0440\u0438 \u0441\u043E\u0437\u0434\u0430\u043D\u0438\u0438 \u0441\u0442\u043E\u043B\u0430 \u0432\u044B\u0431\u0435\u0440\u0438 \u0412\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0435 \u0444\u0438\u0448\u043A\u0438 \u0432 \u0420\u0430\u0441\u0447\u0451\u0442\u0435 \u0440\u0430\u0443\u043D\u0434\u0430 \u0434\u043B\u044F \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u0445 \u0432\u0437\u043D\u043E\u0441\u043E\u0432 \u0438 \u0442\u043E\u0440\u0433\u043E\u0432 \u043F\u0435\u0440\u0435\u0434 \u0431\u0440\u043E\u0441\u043A\u0430\u043C\u0438. \u041D\u0430\u0441\u0442\u0440\u043E\u0439 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u0439 \u0431\u0430\u043B\u0430\u043D\u0441, \u0432\u0437\u043D\u043E\u0441 \u0438 \u0447\u0438\u0441\u043B\u043E \u0440\u0430\u0443\u043D\u0434\u043E\u0432. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E 100 \u0444\u0438\u0448\u0435\u043A, \u0432\u0437\u043D\u043E\u0441 \u0434\u0435\u0441\u044F\u0442\u044C \u0438 \u0434\u0435\u0441\u044F\u0442\u044C \u0440\u0430\u0443\u043D\u0434\u043E\u0432. \u0420\u0435\u0436\u0438\u043C \u043E\u0447\u043A\u043E\u0432 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0441\u0432\u043E\u0439 \u0441\u0447\u0451\u0442 \u0431\u0435\u0437 \u0442\u043E\u0440\u0433\u043E\u0432 \u0444\u0438\u0448\u043A\u0430\u043C\u0438.",
              "\u041F\u043E\u0441\u043B\u0435 \u0442\u043E\u0440\u0433\u043E\u0432 \u0431\u0440\u043E\u0441\u0430\u044E\u0442 \u0432\u0441\u0435 \u043D\u0435 \u0441\u043F\u0430\u0441\u043E\u0432\u0430\u0432\u0448\u0438\u0435, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0432\u0430-\u0431\u0430\u043D\u043A. \u0412\u0437\u043D\u043E\u0441\u044B \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0439 \u0438 \u043F\u043E\u0431\u043E\u0447\u043D\u044B\u0435 \u0431\u0430\u043D\u043A\u0438: \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C \u043C\u043E\u0436\u043D\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u043B\u043E\u0438, \u043F\u043E\u043A\u0440\u044B\u0442\u044B\u0435 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u043C \u0432\u0437\u043D\u043E\u0441\u043E\u043C. \u041A\u0430\u0436\u0434\u044B\u0439 \u0441\u043B\u043E\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0430\u044F \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0430\u044F \u0441\u0443\u043C\u043C\u0430 \u0434\u043E 21; \u0440\u0430\u0432\u043D\u044B\u0435 \u043C\u0430\u043A\u0441\u0438\u043C\u0443\u043C\u044B \u0434\u0435\u043B\u044F\u0442 \u0435\u0433\u043E, \u043E\u0441\u0442\u0430\u0442\u043A\u0438 \u0438\u0434\u0443\u0442 \u043F\u043E \u043F\u043E\u0440\u044F\u0434\u043A\u0443 \u043C\u0435\u0441\u0442 \u0440\u0430\u0443\u043D\u0434\u0430. \u041D\u0435\u0443\u0440\u0430\u0432\u043D\u0435\u043D\u043D\u044B\u0439 \u0438\u0437\u0431\u044B\u0442\u043E\u043A \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F. \u0421\u043B\u043E\u0439 \u0431\u0435\u0437 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0439 \u0441\u0443\u043C\u043C\u044B \u0434\u043E 21 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u0432\u043A\u043B\u0430\u0434\u0447\u0438\u043A\u0430\u043C. \u0415\u0441\u043B\u0438 \u0432\u0441\u0435 \u043A\u0440\u043E\u043C\u0435 \u043E\u0434\u043D\u043E\u0433\u043E \u0441\u043F\u0430\u0441\u043E\u0432\u0430\u043B\u0438, \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0439\u0441\u044F \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043E\u0441\u043F\u0430\u0440\u0438\u0432\u0430\u0435\u043C\u044B\u0439 \u0431\u0430\u043D\u043A \u0431\u0435\u0437 \u0431\u0440\u043E\u0441\u043A\u043E\u0432. \u041E\u0431\u0449\u0435\u0435 \u0447\u0438\u0441\u043B\u043E \u0444\u0438\u0448\u0435\u043A \u0432 \u0431\u0430\u043B\u0430\u043D\u0441\u0430\u0445 \u0438 \u0431\u0430\u043D\u043A\u0430\u0445 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F.",
              "\u041D\u0430\u0447\u0438\u043D\u0430\u044E\u0449\u0438\u0439 \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043A\u0430\u0436\u0434\u044B\u0439 \u0440\u0430\u0443\u043D\u0434. \u041D\u043E\u043B\u044C \u0444\u0438\u0448\u0435\u043A \u0438\u0441\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u0441\u043B\u0435 \u0440\u0430\u0441\u0447\u0451\u0442\u0430. \u041C\u0430\u0442\u0447 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043B\u0438\u043C\u0438\u0442\u043E\u043C \u0440\u0430\u0443\u043D\u0434\u043E\u0432 \u0438\u043B\u0438 \u043A\u043E\u0433\u0434\u0430 \u0441 \u0444\u0438\u0448\u043A\u0430\u043C\u0438 \u043C\u0435\u043D\u044C\u0448\u0435 \u0434\u0432\u0443\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u043A\u043E\u043D\u0435\u0447\u043D\u044B\u0439 \u0431\u0430\u043B\u0430\u043D\u0441; \u0440\u0430\u0432\u043D\u044B\u0435 \u043C\u0430\u043A\u0441\u0438\u043C\u0443\u043C\u044B \u0434\u0430\u044E\u0442 \u043D\u0438\u0447\u044C\u044E. S \u0447\u0438\u0442\u0430\u0435\u0442 \u0431\u0430\u043B\u0430\u043D\u0441\u044B. \u0420\u0430\u043D\u0435\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0435 \u0438\u0433\u0440\u044B \u043D\u0430 \u0444\u0438\u0448\u043A\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442 \u043F\u0440\u0435\u0436\u043D\u0438\u0435 \u0442\u043E\u0440\u0433\u0438."),
            rule_section(:controls, "\u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435",
              "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. Tab \u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u043B\u0435. T \u0447\u0438\u0442\u0430\u0435\u0442 \u0445\u043E\u0434, S \u0441\u0447\u0451\u0442, F1 \u0442\u0435\u043A\u0443\u0449\u0438\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F, Ctrl+F1 \u043F\u0440\u0430\u0432\u0438\u043B\u0430. \u0420\u0443\u043A\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043B\u0438\u0447\u043D\u043E\u0441\u0442\u044C \u043A\u0430\u0440\u0442 \u0438 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F. \u041A\u0430\u0440\u0442\u044B \u0441\u043B\u0443\u0436\u0430\u0442 \u0434\u043B\u044F \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0430; \u0440\u0435\u0448\u0435\u043D\u0438\u044F \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u0432 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F\u0445.")
          ]
